import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.DaGSOal_.js";const h=JSON.parse('{"title":"B","description":"","frontmatter":{},"headers":[],"relativePath":"glossaire-a-z/b.md","filePath":"glossaire-a-z/b.md"}'),l={name:"glossaire-a-z/b.md"};function s(n,e,i,d,c,u){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="b" tabindex="-1">B <a class="header-anchor" href="#b" aria-label="Permalink to &quot;B&quot;">​</a></h1><h2 id="babbage" tabindex="-1">Babbage <a class="header-anchor" href="#babbage" aria-label="Permalink to &quot;Babbage&quot;">​</a></h2><p>Babbage est une ère du registre (<em>ledger era</em>) de Cardano, introduite lors de la mise à niveau Vasil en septembre 2022. Associée à la phase de développement Basho, elle a apporté plusieurs fonctionnalités importantes pour améliorer l’efficacité du réseau et l’expérience des développeurs, notamment les <em>reference inputs</em> (entrées de référence), les <em>inline datums</em> (données intégrées) et les <em>reference scripts</em> (scripts de référence).</p><p>Ces améliorations facilitent le développement de contrats intelligents et contribuent à l’évolutivité du réseau.</p><p>→ <a href="https://docs.cardano.org/about-cardano/evolution/eras-and-phases" target="_blank" rel="noreferrer">Development phases and eras — Cardano Docs</a></p><h2 id="babel-fees" tabindex="-1">Babel Fees <a class="header-anchor" href="#babel-fees" aria-label="Permalink to &quot;Babel Fees&quot;">​</a></h2><p>Les Babel Fees désignent un mécanisme proposé qui permettrait aux utilisateurs de payer les frais de transaction avec des jetons natifs plutôt qu’avec de l’ada. Ce mécanisme n’est pas encore actif sur le réseau principal.</p><p>→ <a href="https://developers.cardano.org/docs/learn/core-concepts/fees/" target="_blank" rel="noreferrer">Frais de transaction — Cardano Developer Portal</a></p><h2 id="balance-wallet-fr-portefeuille-a-solde-global" tabindex="-1">Balance Wallet (fr : Portefeuille à solde global) <a class="header-anchor" href="#balance-wallet-fr-portefeuille-a-solde-global" aria-label="Permalink to &quot;Balance Wallet (fr : Portefeuille à solde global)&quot;">​</a></h2><p>Un Balance Wallet est un type de portefeuille Cardano qui affiche le solde total en ada ou en jetons sous la forme d’un seul montant, plutôt que d’afficher individuellement les sorties de transaction non dépensées (<em>UTXO</em>) qui composent ce solde. Il simplifie le modèle UTXO pour les utilisateurs en masquant les détails techniques de la structure des fonds sur la blockchain.</p><h2 id="basho" tabindex="-1">Basho <a class="header-anchor" href="#basho" aria-label="Permalink to &quot;Basho&quot;">​</a></h2><p>Basho est la quatrième phase de la feuille de route de développement de Cardano, axée sur l’évolutivité et l’optimisation. L’ère Basho a amélioré le débit et l’efficacité du réseau grâce à des fonctionnalités telles que le <em>sharding</em> et les chaînes latérales (<em>sidechains</em>). Son nom fait référence à Matsuo Bashō, poète japonais et maître du haïku.</p><p>→ <a href="https://docs.cardano.org/about-cardano/explore-more/relevant-research-papers" target="_blank" rel="noreferrer">Recherches et publications sur Basho — Cardano Docs</a></p><h2 id="bech32" tabindex="-1">Bech32 <a class="header-anchor" href="#bech32" aria-label="Permalink to &quot;Bech32&quot;">​</a></h2><p>Bech32 est un format d’encodage des adresses utilisé pour les adresses Cardano depuis le hard fork Shelley.</p><p>→ <a href="https://developers.cardano.org/docs/learn/core-concepts/addresses/" target="_blank" rel="noreferrer">Adresses — Cardano Developer Portal</a></p><h2 id="block-fr-bloc" tabindex="-1">Block (fr : Bloc) <a class="header-anchor" href="#block-fr-bloc" aria-label="Permalink to &quot;Block (fr : Bloc)&quot;">​</a></h2><p>Un bloc est une unité de données contenant un ensemble de transactions ajoutées à la blockchain.</p><h2 id="blockperf" tabindex="-1">Blockperf <a class="header-anchor" href="#blockperf" aria-label="Permalink to &quot;Blockperf&quot;">​</a></h2><p>Blockperf est un outil open source utilisé par les opérateurs de pools de staking pour mesurer la rapidité avec laquelle leurs nœuds reçoivent et transmettent les blocs nouvellement produits.</p><h2 id="bribery-attack-fr-attaque-par-corruption" tabindex="-1">Bribery Attack (fr : Attaque par corruption) <a class="header-anchor" href="#bribery-attack-fr-attaque-par-corruption" aria-label="Permalink to &quot;Bribery Attack (fr : Attaque par corruption)&quot;">​</a></h2><p>Une attaque par corruption est une attaque dans laquelle un attaquant externe rémunère des validateurs pour les inciter à agir à l’encontre du protocole, par exemple en signant des blocs contradictoires ou en transmettant des clés dormantes.</p><h2 id="bridge-fr-pont-blockchain" tabindex="-1">Bridge (fr : Pont blockchain) <a class="header-anchor" href="#bridge-fr-pont-blockchain" aria-label="Permalink to &quot;Bridge (fr : Pont blockchain)&quot;">​</a></h2><p>Un bridge est un protocole qui relie Cardano à une autre blockchain afin de permettre le transfert d’actifs ou de messages entre les deux réseaux. Il repose généralement sur une paire de contrats : l’un verrouille une valeur sur une blockchain et l’autre émet une représentation de cette valeur sur l’autre blockchain.</p><h2 id="byron" tabindex="-1">Byron <a class="header-anchor" href="#byron" aria-label="Permalink to &quot;Byron&quot;">​</a></h2><p>Byron est la première ère de développement de Cardano. Elle a établi les fondations du réseau.</p>',26)])])}const b=a(l,[["render",s]]);export{h as __pageData,b as default};
